function normalizeDemoState(data){(data.visits||[]).forEach(v=>(v.guests||[]).forEach(g=>{g.formToken=g.formToken||uid();g.guideToken=g.guideToken||uid();g.profile=g.profile||{};g.formStatus=g.formStatus||(g.profile.phone?'complete':'not-sent');}));data.notifications=data.notifications||[];data.visitRequests=data.visitRequests||(data.visits&&data.visits.length?[{id:'request-demo-marc',name:'Boston Lighting Studio Preview',city:'Boston',country:'United States',startDate:dateOffset(35),endDate:dateOffset(37),createdBy:'marc',sales:['nina'],status:'pending',createdAt:new Date().toISOString()}]:[]);data.demoUserId=data.demoUserId||(data.role==='VP'?'marc':data.role==='SALES'?'nina':'monse');return data;}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));if(saved&&Array.isArray(saved.visits)){saved.visits.forEach(v=>(v.activity||[]).forEach(a=>{if(a.actor==='Monse Caron')a.actor='Monserrat Jimenez';}));return normalizeDemoState(saved);}}catch(e){}return normalizeDemoState(seedData());}
let state=loadState();
let currentProfile=null;
let backendActive=false;
let page={name:'overview',visitId:null,tab:'Overview',view:'list',filter:'All statuses',search:'',onlyReview:false,month:new Date(new Date().getFullYear(),new Date().getMonth(),1)};
let modalSubmit=null;
const appContent=document.getElementById('appContent');
function persist(){updateNav();if(backendActive){window.AxisSupabaseBackend.saveState(state).catch(error=>{console.error('Supabase save failed.',error);toast('Could not sync changes: '+(error.message||'connection error'),true);});return true;}try{localStorage.setItem(STORE_KEY,JSON.stringify(state));return true;}catch(e){toast('Browser storage is full. Remove a large attachment and try again.',true);return false;}}
function updateNav(){const live=state.visits.filter(v=>!v.archived);document.getElementById('navVisitCount').textContent=live.length;document.getElementById('navReviewCount').textContent=live.reduce((n,v)=>n+reviewCount(v),0);document.getElementById('roleSelect').value=state.demoUserId||'monse';const activePage=page.onlyReview?'needs-review':page.name==='detail'?(state.visits.find(v=>v.id===page.visitId)?.archived?'archives':'all-visits'):page.name;document.querySelectorAll('[data-nav-page]').forEach(link=>{const active=link.dataset.navPage===activePage;link.classList.toggle('active',active);link.setAttribute('aria-current',active?'page':'false');});}
function setMobileMenu(open){const sidebar=document.getElementById('sidebarMenu'),backdrop=document.querySelector('.mobile-nav-backdrop'),trigger=document.getElementById('mobileMenuButton'),mobile=window.matchMedia('(max-width: 720px)').matches,wasOpen=sidebar.classList.contains('is-open');sidebar.classList.toggle('is-open',open);backdrop.hidden=!open;document.body.classList.toggle('mobile-menu-open',open);sidebar.inert=mobile&&!open;sidebar.setAttribute('aria-hidden',mobile&&!open?'true':'false');trigger.setAttribute('aria-expanded',String(open));trigger.setAttribute('aria-label',open?'Close navigation':'Open navigation');if(!open&&wasOpen&&mobile)trigger.focus({preventScroll:true});}
function esc(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function person(id){return people.find(p=>p.id===id)||{id:'',name:'Unassigned',initials:'—',role:''};}
function personName(id){return person(id).name;}
function currentUserId(){return currentProfile?.id||state.demoUserId||(state.role==='VP'?'marc':state.role==='SALES'?'nina':'monse');}
function canView(v){if(state.role==='SUPER_ADMIN')return true;const id=currentUserId();return v.lead===id||v.collaborators.includes(id)||v.sales.includes(id);}
function reviewCount(v){return v.bookings.filter(b=>b.needsReview).length;}
function activeBookings(v,type){return v.bookings.filter(b=>(!type||b.type===type)&&b.status!=='Cancelled');}
function progress(v,type){const list=activeBookings(v,type);return list.length?Math.round(list.filter(b=>b.status==='Done').length/list.length*100):null;}
function fmtDate(s, options={month:'short',day:'numeric'}){if(!s)return '—';const d=new Date(`${s}T12:00:00`);return new Intl.DateTimeFormat('en-US',options).format(d);}
function fmtRange(start,end){if(!start&&!end)return 'Dates to be confirmed';if(start&&end){const a=new Date(`${start}T12:00:00`),b=new Date(`${end}T12:00:00`);if(a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth())return `${fmtDate(start)} – ${fmtDate(end,{day:'numeric'})}`;return `${fmtDate(start,{month:'short',day:'numeric',year:'numeric'})} – ${fmtDate(end,{month:'short',day:'numeric',year:'numeric'})}`;}return fmtDate(start||end,{month:'short',day:'numeric',year:'numeric'});}
function statusClass(status){return `status-${status.toLowerCase().replaceAll(' ','-')}`;}
function statusPill(status){return `<span class="status-pill ${statusClass(status)}">${esc(status)}</span>`;}
function themeClass(v){return ({terracotta:'thumb-terracotta',blue:'thumb-blue',sage:'thumb-sage',night:'thumb-night'})[v.theme]||'';}
function iconFor(type){return ({Flight:'✈',Hotel:'⌂',Transportation:'↗',Restaurant:'◌',Activity:'✳'})[type]||'•';}
function personAvatar(id){const p=person(id);return `<span class="mini-avatar" title="${esc(p.name)}">${esc(p.initials)}</span>`;}
function guestAvatar(g){return `<span class="mini-avatar" title="${esc(g.firstName+' '+g.lastName)}">${esc((g.firstName[0]||'')+(g.lastName[0]||''))}</span>`;}
function canEditFlightData(v){return canEdit(v)||canManageGuestData(v);}
function canEditBooking(v,b){return canEdit(v)||(b?.type==='Flight'&&canManageGuestData(v));}
function log(v,action,detail){if(!canEdit(v)&&!canManageGuestData(v))return;const actor=currentProfile?([currentProfile.first_name,currentProfile.last_name].filter(Boolean).join(' ')||currentProfile.email):state.role==='SUPER_ADMIN'?'Monserrat Jimenez':person(currentUserId()).name;v.activity.unshift({id:uid(),actorId:currentProfile?.id||'',actor,action,detail,at:new Date().toISOString()});}
function guestPortalUrl(kind,token){const url=new URL(window.location.href);url.search='';url.hash='';url.searchParams.set('demo','guest');url.searchParams.set(kind,token);return url.href;}
function makeDemoNotification(userId,visit,title,message){if(!userId)return;state.notifications.push({id:uid(),userId,visitId:visit.id,title,message,createdAt:new Date().toISOString(),read:false});}
function notifyVisitTeam(visit){if(backendActive)return;const recipientIds=[visit.lead,...visit.collaborators,...visit.sales];[...new Set(recipientIds)].forEach(id=>makeDemoNotification(id,visit,'New visit assigned',`${visit.name} · ${fmtRange(visit.startDate,visit.endDate)}. You have been added to the visit team.`));}
function currentNotifications(){return (state.notifications||[]).filter(n=>n.userId===currentUserId()).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));}
function canEdit(v){if(state.role==='SUPER_ADMIN')return true;if(state.role==='SALES'||['Completed','Cancelled'].includes(v.status))return false;const id=currentUserId();return v.lead===id||v.collaborators.includes(id);}
function canManageGuestData(v){if(canEdit(v))return true;if(state.role!=='SALES'||['Completed','Cancelled'].includes(v.status)||v.archived)return false;return (v.sales||[]).includes(currentUserId());}
function canManageBookingStatus(){return state.role==='SUPER_ADMIN';}
function categoryCounts(v,type){return bookingStatuses.map(s=>[s,v.bookings.filter(b=>b.type===type&&b.status===s).length]);}
function sortedVisits(list){return [...list].sort((a,b)=>(a.startDate||'9999').localeCompare(b.startDate||'9999'));}

function dashboardItems(){
  const archived=page.name==='archives';
  let items=state.visits.filter(v=>!!v.archived===archived&&canView(v));
  if(page.filter!=='All statuses')items=items.filter(v=>v.status===page.filter);
  if(page.onlyReview)items=items.filter(v=>reviewCount(v)>0);
  if(page.search){const q=page.search.toLowerCase();items=items.filter(v=>`${v.name} ${v.city} ${v.country} ${personName(v.lead)}`.toLowerCase().includes(q));}
  return sortedVisits(items);
}
function renderDashboard(){
  const archived=page.name==='archives', overview=page.name==='overview'&&!page.onlyReview, allVisits=page.name==='all-visits', visits=dashboardItems();
  const live=state.visits.filter(v=>!v.archived&&canView(v)), upcoming=live.filter(v=>['Upcoming','In Progress'].includes(v.status)), needing=live.reduce((n,v)=>n+reviewCount(v),0), guestTotal=live.reduce((n,v)=>n+v.guests.filter(g=>g.status!=='Cancelled').length,0);
  const overviewVisits=sortedVisits(live.filter(v=>['Planning','Upcoming','In Progress'].includes(v.status))).slice(0,4);
  const title=archived?'Archived visits':page.onlyReview?'Needs review':page.name==='settings'?'Workspace settings':overview?'Overview':allVisits?'All visits':'Your visits';
  document.getElementById('breadcrumbCurrent').textContent=title;
  appContent.innerHTML=`<div class="page-heading"><div><p class="eyebrow">${archived?'THE ARCHIVE':page.onlyReview?'ATTENTION REQUIRED':overview?"YOUR WORKSPACE":new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date()).toUpperCase()}</p><h1>${title}</h1><p class="page-subtitle">${archived?'Past plans, kept close at hand.':page.onlyReview?'A quick look at the details that need a second look.':overview?'A snapshot of upcoming visits and the details that need attention.':page.name==='settings'?'Manage this local demo workspace.':`Browse and filter every active customer visit.`}</p></div>${state.role==='SUPER_ADMIN'&&!archived&&!page.onlyReview&&page.name!=='settings'?`<button class="primary-button" data-action="new-visit"><span class="plus">+</span> Create a visit</button>`:''}</div>
    ${page.name==='settings'?renderSettings():`${overview?`<section class="stats-grid">
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Active visits</span><span class="stat-icon coral">▤</span></div><div class="stat-number">${live.length}<span class="stat-foot">on your board</span></div><i class="stat-hairline"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Coming up</span><span class="stat-icon blue">↗</span></div><div class="stat-number">${upcoming.length}<span class="stat-foot">next 30 days</span></div><i class="stat-hairline" style="width:52%;background:linear-gradient(90deg,#819cb7,#c8d9e3)"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Guests</span><span class="stat-icon green">♧</span></div><div class="stat-number">${guestTotal}<span class="stat-foot">across all visits</span></div><i class="stat-hairline" style="width:64%;background:linear-gradient(90deg,#86ae93,#cde1d2)"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Needs review</span><span class="stat-icon gold">◉</span></div><div class="stat-number">${needing}<span class="stat-foot">bookings flagged</span></div><i class="stat-hairline" style="width:${needing?38:0}%;background:linear-gradient(90deg,#e5a276,#f4d1b8)"></i></div>
    </section>`:''}
    <div class="dashboard-grid ${overview?'overview-dashboard':''} ${allVisits&&!page.onlyReview?'all-visits-dashboard':''}"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">${overview?'Upcoming visits':archived?'Archived visits':page.onlyReview?'Bookings to review':'Visit schedule'}</h2><p class="panel-caption">${overview?`${overviewVisits.length} upcoming ${overviewVisits.length===1?'visit':'visits'} · next on your calendar`:archived?'Your completed and paused plans':`${visits.length} ${visits.length===1?'visit':'visits'} · updated just now`}</p></div>${overview?`<button class="small-link" data-action="all-visits">View all visits →</button>`:allVisits&&!page.onlyReview?`<div class="view-switch"><button data-view="list" class="${page.view==='list'?'active':''}">☷ &nbsp;List</button><button data-view="calendar" class="${page.view==='calendar'?'active':''}">▦ &nbsp;Calendar</button></div>`:''}</div>
      ${allVisits||archived||page.onlyReview?renderToolbar(archived):''}${overview?renderVisitTable(overviewVisits,false):page.view==='calendar'&&allVisits&&!page.onlyReview?renderCalendar(visits):renderVisitTable(visits,archived)}
      ${overview?`<div class="table-footer"><span>Next customer visits</span><button class="small-link" data-action="all-visits">See all ${live.length} visits →</button></div>`:visits.length?`<div class="table-footer"><span>Showing <b>${visits.length}</b> ${visits.length===1?'visit':'visits'}</span><span>${archived?`<button class="small-link" data-action="all-visits">Back to active visits →</button>`:'Your workspace · Eastern Time'}</span></div>`:''}</section>
      ${overview?renderSideStack(live):allVisits&&!page.onlyReview?'':`<aside class="side-stack">${renderQuickGuide()}</aside>`}</div>`}`;
  updateNav();
}
function renderToolbar(archived){return `<div class="visit-toolbar"><label class="search-box"><svg viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="visitSearch" placeholder="Search visits or destinations" value="${esc(page.search)}" /></label><select class="filter-select" id="statusFilter"><option>All statuses</option>${visitStatuses.map(s=>`<option ${page.filter===s?'selected':''}>${s}</option>`).join('')}</select>${!archived?`<label class="filter-check"><input id="reviewFilter" type="checkbox" ${page.onlyReview?'checked':''}> Needs review</label>`:''}</div>`;}
function renderVisitTable(visits,archived){
 if(!visits.length)return `<div class="empty-state"><div class="empty-symbol">${archived?'▣':'◌'}</div><h3>${archived?'Nothing archived yet':'No visits match this view'}</h3><p>${archived?'Visits you archive will stay here, ready to restore.':'Try another filter or start planning a new customer visit.'}</p>${state.role==='SUPER_ADMIN'&&!archived&&!page.onlyReview?`<button class="primary-button" data-action="new-visit"><span class="plus">+</span> Create a visit</button>`:''}</div>`;
 return `<div class="mobile-visit-list" aria-label="Visits">${visits.map(v=>`<article class="mobile-visit-card" role="button" tabindex="0" data-open-visit="${v.id}"><div class="mobile-visit-card-head"><div class="visit-name"><span class="visit-thumb ${themeClass(v)}"></span><span><strong>${esc(v.name)}</strong><small>${v.guests.filter(g=>g.status!=='Cancelled').length} guests · ${v.bookings.length} bookings</small></span></div>${statusPill(v.status)}</div><div class="mobile-visit-card-details"><div><span>Destination</span><strong>${v.city?`${esc(v.city)}, ${esc(v.country)}`:'Not set'}</strong></div><div><span>Dates</span><strong>${fmtRange(v.startDate,v.endDate)}</strong></div><div><span>Lead VP</span><strong class="mobile-visit-lead">${personAvatar(v.lead)}${esc(personName(v.lead).split(' ')[0])}</strong></div></div>${reviewCount(v)?`<span class="review-badge">${reviewCount(v)} to review</span>`:''}<span class="mobile-visit-open" aria-hidden="true">View visit <b>›</b></span></article>`).join('')}</div><div class="table-wrap"><table class="visit-table"><thead><tr><th>Visit</th><th>Destination</th><th>Dates</th><th>Lead VP</th><th>Status</th><th>Needs review</th><th></th></tr></thead><tbody>${visits.map(v=>`<tr data-open-visit="${v.id}"><td><div class="visit-name"><span class="visit-thumb ${themeClass(v)}"></span><span><strong>${esc(v.name)}</strong><small>${v.guests.filter(g=>g.status!=='Cancelled').length} guests · ${v.bookings.length} bookings</small></span></div></td><td class="destination-cell">${v.city?`${esc(v.city)}, ${esc(v.country)}`:'<span class="review-empty">Not set</span>'}</td><td class="date-cell">${fmtRange(v.startDate,v.endDate)}</td><td><span class="lead-cell">${personAvatar(v.lead)}${esc(personName(v.lead).split(' ')[0])}</span></td><td>${statusPill(v.status)}</td><td>${reviewCount(v)?`<span class="review-badge">${reviewCount(v)} to review</span>`:'<span class="review-empty">—</span>'}</td><td><button class="row-menu" data-row-menu="${v.id}" aria-label="Visit options">···</button></td></tr>`).join('')}</tbody></table></div>`;
}
function renderSideStack(live){
 const review=live.flatMap(v=>v.bookings.filter(b=>b.needsReview).map(b=>({v,b}))).slice(0,3);
 const agenda=sortedVisits(live.filter(v=>v.startDate&&v.status!=='Completed'&&v.status!=='Cancelled')).slice(0,3);
 return `<aside class="side-stack"><section class="panel review-panel"><div class="panel-head"><div><h2 class="panel-title">Needs your attention</h2><p class="panel-caption">${review.length?`${reviewCount({bookings:live.flatMap(v=>v.bookings)})} bookings need a look`:'All clear for now'}</p></div><button class="small-link" data-action="needs-review">View all</button></div><div class="review-list">${review.length?review.map(({v,b})=>`<div class="review-item" data-open-visit="${v.id}" data-open-tab="${b.type==='Flight'?'Flights':b.type==='Hotel'?'Hotels':b.type==='Transportation'?'Transportation':b.type==='Restaurant'?'Restaurants':'Activities'}"><i class="review-indicator"></i><div><strong>${esc(b.name)}</strong><p>${esc(v.name)} · ${esc(b.reviewReason||'Review booking details')}</p></div><span class="review-arrow">›</span></div>`).join(''):`<div class="agenda-empty">Any booking flags will appear here.</div>`}</div></section><section class="panel agenda-panel"><div class="panel-head"><div><h2 class="panel-title">Coming up</h2><p class="panel-caption">The next dates on your calendar</p></div><span class="stat-icon blue">◷</span></div>${agenda.length?agenda.map(v=>`<div class="agenda-day" data-open-visit="${v.id}"><div class="agenda-date"><b>${fmtDate(v.startDate,{day:'numeric'})}</b><span>${fmtDate(v.startDate,{month:'short'})}</span></div><div class="agenda-copy"><strong>${esc(v.name)}</strong><small>${esc(v.city||'Destination TBD')} · ${esc(personName(v.lead).split(' ')[0])}</small></div><i class="agenda-mark"></i></div>`).join(''):`<div class="agenda-empty">No visits scheduled yet.</div>`}</section></aside>`;
}
function renderQuickGuide(){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">A little more room</h2><p class="panel-caption">Your visits stay organized here</p></div></div><div class="review-list"><div class="review-item"><i class="review-indicator" style="background:#8da89a;box-shadow:0 0 0 4px #edf4ef"></i><div><strong>Everything in one place</strong><p>Guests, bookings and trip details, all together.</p></div></div><div class="review-item"><i class="review-indicator" style="background:#92aab8;box-shadow:0 0 0 4px #eff4f7"></i><div><strong>Pick up where you left off</strong><p>Archived plans are easy to restore anytime.</p></div></div></div></section>`;}
function renderCalendar(visits){
 const month=new Date(page.month.getFullYear(),page.month.getMonth(),1),monthEnd=new Date(month.getFullYear(),month.getMonth()+1,0),offset=(month.getDay()+6)%7,start=new Date(month);start.setDate(month.getDate()-offset);const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);cells.push(d);}
 const ymd=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);
 return `<div class="calendar-panel"><div class="calendar-head"><h2>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(month)}</h2><div class="calendar-nav"><button data-month="prev">‹</button><button data-month="today">Today</button><button data-month="next">›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-day-label">${d}</div>`).join('')}${cells.map(d=>{const date=ymd(d),events=visits.filter(v=>v.startDate&&v.endDate&&date>=v.startDate&&date<=v.endDate);return `<div class="calendar-day ${d.getMonth()!==month.getMonth()?'outside':''} ${date===todayISO()?'today':''}"><span class="calendar-day-number">${d.getDate()}</span>${events.slice(0,2).map(v=>`<div class="calendar-event ${v.status.toLowerCase().replaceAll(' ','-')}" data-open-visit="${v.id}">${esc(v.name)}</div>`).join('')}${events.length>2?`<div class="calendar-event">+${events.length-2} more</div>`:''}</div>`;}).join('')}</div><div class="calendar-legend"><span><i class="legend-dot"></i>Upcoming</span><span><i class="legend-dot" style="background:#c4a568"></i>Planning</span><span><i class="legend-dot" style="background:#66a786"></i>In progress</span></div></div>`;
}
function notificationPermission(){return 'Notification' in window?Notification.permission:'unsupported';}
function notificationSettingsCard(){const permission=notificationPermission(),copy=permission==='granted'?'Browser permission is enabled on this device. Automatic shared-visit push alerts are a separate setup step.':permission==='denied'?'Notifications are blocked by this browser or device. Allow them in your device settings to enable this app.':permission==='unsupported'?'This browser does not support web notifications.':'Notifications are off on this device.';const action=permission==='default'?'<button class="secondary-button" data-action="enable-notifications">Enable notifications</button>':permission==='denied'?'<button class="secondary-button" data-action="notification-help">How to enable</button>':permission==='granted'?'<button class="secondary-button" data-action="test-notification">Send a test notification</button>':'';return '<div class="notification-settings"><div class="notification-settings-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4"/></svg></div><div class="notification-settings-copy"><h3>Device notifications</h3><p>'+esc(copy)+'</p></div>'+(permission==='granted'?'<span class="notification-state is-enabled">Enabled</span>':'')+action+'</div>';}
function canInviteTeamMembers(){return backendActive&&['SUPER_ADMIN','VP'].includes(state.role);}
function renderInviteTeamMemberCard(){if(!canInviteTeamMembers())return '';const roleField=state.role==='SUPER_ADMIN'?selectField('inviteRole','Role',[{value:'SALES',label:'Sales rep'},{value:'VP',label:'Vice President'}],'SALES',false):'<input type="hidden" name="inviteRole" value="SALES"><div class="form-help">VPs can invite Sales reps.</div>';return '<div class="invite-team-card"><div class="section-title-row"><div><h3>Invite a team member</h3><p>They will receive an email invitation to Axis Visits.</p></div></div><form id="inviteRepForm"><div class="form-grid">'+field('inviteFirstName','First name')+field('inviteLastName','Last name')+'<div class="form-field full"><label for="inviteEmail">Email address <span style="color:#d94f37">*</span></label><input id="inviteEmail" name="inviteEmail" type="email" required autocomplete="email"></div>'+roleField+'<div class="form-field full"><button class="primary-button" type="submit">Send invitation</button></div></div></form></div>';}
function renderSettings(){if(backendActive){const needsVp=!people.some(p=>p.role==='VP');return '<section class="panel settings-panel"><p class="eyebrow">SHARED WORKSPACE</p><h2 class="panel-title">Account & workspace</h2><p class="page-subtitle">Visit and booking updates are saved to the shared Axis Visits database.</p><div class="settings-account"><span class="avatar">'+esc(((currentProfile.first_name||currentProfile.email||'A')[0]||'A').toUpperCase())+'</span><div><strong>'+esc([currentProfile.first_name,currentProfile.last_name].filter(Boolean).join(' ')||currentProfile.email)+'</strong><span>'+esc(currentProfile.email)+' · '+esc(currentProfile.global_role)+'</span></div></div>'+(needsVp?'<div class="notice-banner"><strong>One setup item:</strong> Invite an active VP account in Supabase Authentication before creating visits.</div>':'')+'<div class="notice-banner"><strong>Access control:</strong> Permissions are enforced by account roles and database security policies.</div>'+notificationSettingsCard()+renderInviteTeamMemberCard()+'<div class="section-title-row"><div><h3>Sign out</h3><p>Sign out of Axis Visits on this device.</p></div><button class="secondary-button" data-action="sign-out">Sign out</button></div></section>';}return '<section class="panel"><h2 class="panel-title">Workspace settings</h2><p class="page-subtitle">Use a secure HTTPS address to connect to the shared workspace.</p></section>';}
function notificationPromptKey(){return 'axis-visits-presentation-demo-notification-prompt-v1:'+currentUserId();}
function showNotificationPrompt(){const supported=notificationPermission()!=='unsupported'&&'serviceWorker' in navigator;openModal('Stay up to date',`<div class="notification-optin"><div class="notification-optin-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4"/></svg></div><p class="confirmation-copy">Turn on notifications for this device so Axis Visits can keep you informed about important visit updates.</p>${supported?'<p class="notification-optin-note">Your browser will ask for permission. You can change it later in Workspace Settings. Automatic shared-visit alerts are the next setup step.</p>':'<p class="notification-optin-note">This browser does not support notifications. Open Axis Visits in a supported browser or installed app.</p>'}</div>`,`<button class="secondary-button" data-action="dismiss-notifications">Maybe later</button>${supported?'<button class="primary-button" data-action="enable-notifications">Enable notifications</button>':''}`,null);}
function maybePromptForNotifications(){if(!backendActive||notificationPermission()!=='default')return;try{if(localStorage.getItem(notificationPromptKey()))return;}catch(error){}setTimeout(()=>{if(backendActive&&notificationPermission()==='default'&&document.getElementById('modalBackdrop').hidden)showNotificationPrompt();},350);}
async function sendTestNotification(){if(Notification.permission!=='granted'){toast('Enable notifications on this device first.',true);return;}try{const registration=await navigator.serviceWorker.ready;if(!registration.showNotification)throw new Error('Notifications are not available in this browser.');await registration.showNotification('Axis Visits · Test', {body:'Notifications are enabled on this device.',icon:'./axis-visits-icon-192.png',badge:'./axis-visits-icon-192.png',tag:'axis-visits-test',data:{url:window.location.href}});toast('A test notification was sent to this device.');}catch(error){toast(error.message||'Could not display a test notification.',true);}}
async function enableNotifications(){if(notificationPermission()==='unsupported'||!('serviceWorker' in navigator)){toast('Notifications are not supported in this browser.',true);return;}if(Notification.permission==='denied'){toast('Notifications are blocked. Allow them in your device settings.',true);return;}try{const permission=await Notification.requestPermission();if(permission==='granted'){try{localStorage.setItem(notificationPromptKey(),'enabled');}catch(error){}closeModal();if(page.name==='settings')render();await sendTestNotification();}else{closeModal();toast(permission==='denied'?'Notifications were blocked. Change this in your device settings.':'Notifications were not enabled.');}}catch(error){closeModal();toast('Could not request notification permission. Try again from Workspace Settings.',true);}}
function showNotificationHelp(){openModal('Allow notifications',`<p class="confirmation-copy">Notifications are currently blocked for this device. Open your browser or device settings, find Axis Visits, and allow notifications. Then return here and refresh the page.</p>`,`<button class="primary-button" data-action="close-modal">Got it</button>`,null);}

function renderDetail(){
  const v=state.visits.find(x=>x.id===page.visitId);if(!v||!canView(v)){page.name='overview';page.visitId=null;return renderDashboard();}
 document.getElementById('breadcrumbCurrent').textContent=v.name;
 const closed=['Completed','Cancelled'].includes(v.status),editable=canEdit(v), tabs=['Overview','Guests','Flights','Hotels','Transportation','Restaurants','Activities','Activity Log'];
 const bookingTotal=v.bookings.length,peopleCount=v.guests.filter(g=>g.status!=='Cancelled').length;
  appContent.innerHTML=`<div class="detail-top"><button class="back-link" data-action="${v.archived?'archives':'all-visits'}">← &nbsp;${v.archived?'Archived visits':'All visits'}</button><div class="detail-actions">${state.role==='SUPER_ADMIN'&&!v.archived?`<button class="quiet-button" data-action="archive-visit" data-id="${v.id}">Archive</button>`:''}${editable?`<button class="secondary-button" data-action="edit-visit" data-id="${v.id}">Edit visit</button>`:''}${state.role==='SUPER_ADMIN'&&v.archived?`<button class="secondary-button" data-action="restore-visit" data-id="${v.id}">Restore visit</button>`:''}</div></div>
    ${v.archived?`<div class="notice-banner archive-banner">This visit is archived. All of its plans, documents and activity remain available.</div>`:''}
    <section class="visit-hero"><div class="hero-art art-${esc(v.theme||'terracotta')}"></div><div class="visit-heading"><p class="eyebrow">CUSTOMER VISIT</p><h1>${esc(v.name)}</h1><div class="visit-subline"><span>${esc(fmtRange(v.startDate,v.endDate))}</span><span class="dot-divider">·</span><span>${esc(v.city?`${v.city}, ${v.country}`:'Destination to be confirmed')}</span><span class="dot-divider">·</span>${statusPill(v.status)}</div></div><div class="detail-meta"><span class="meta-chip">Lead VP ${personAvatar(v.lead)} <b>${esc(personName(v.lead).split(' ')[0])}</b></span><span class="meta-chip"><b>${peopleCount}</b> guests</span></div></section>
    ${closed&&state.role!=='SUPER_ADMIN'?`<p class="access-note">This ${v.status.toLowerCase()} visit is read-only for VPs and Sales.</p>`:''}
    <nav class="tab-bar">${tabs.map(t=>{const type=({Flights:'Flight',Hotels:'Hotel',Transportation:'Transportation',Restaurants:'Restaurant',Activities:'Activity'})[t];return `<button class="tab-button ${page.tab===t?'active':''}" data-tab="${t}">${t==='Activity Log'?'Activity log':t}${t==='Guests'?`<span class="tab-count">${v.guests.length}</span>`:type?`<span class="tab-count">${v.bookings.filter(b=>b.type===type).length}</span>`:''}</button>`;}).join('')}</nav>
    <div class="detail-content">${renderDetailTab(v)}</div>`;
}
function renderDetailTab(v){
 if(page.tab==='Overview')return renderOverview(v);
 if(page.tab==='Guests')return renderGuests(v);
 if(page.tab==='Activity Log')return renderActivity(v);
 const type=page.tab==='Flights'?'Flight':page.tab==='Hotels'?'Hotel':page.tab==='Transportation'?'Transportation':page.tab==='Restaurants'?'Restaurant':'Activity';
 return renderBookings(v,type);
}
function renderOverview(v){
 const fields=[['Destination',v.city?`${v.city}, ${v.country}`:'Not set'],['Start date',fmtDate(v.startDate,{month:'long',day:'numeric',year:'numeric'})],['End date',fmtDate(v.endDate,{month:'long',day:'numeric',year:'numeric'})],['Status',v.status],['Lead VP',personName(v.lead)],['Collaborators',v.collaborators.length?v.collaborators.map(personName).join(', '):'None yet'],['Sales team',v.sales.length?v.sales.map(personName).join(', '):'None yet'],['Guests',`${v.guests.filter(g=>g.status!=='Cancelled').length} active guests`],['Bookings',`${v.bookings.length} total bookings`]];
 return `<div class="overview-grid"><section class="detail-panel"><div class="detail-panel-head"><h3>Visit information</h3><span>${canEdit(v)?`<button class="small-link" data-action="edit-visit" data-id="${v.id}">Edit details</button>`:''}</span></div><div class="info-grid">${fields.map(([k,val])=>`<div class="info-item"><div class="info-label">${k}</div><div class="info-value ${val==='Not set'||val==='None yet'?'subtle':''}">${esc(val)}</div></div>`).join('')}</div>${state.role==='SUPER_ADMIN'?`<div class="detail-panel-head" style="border-top:1px solid #f0f1ee"><h3>Visit status</h3><span>Managed by Monserrat</span></div><div style="padding:0 17px 15px"><button class="secondary-button" data-action="change-visit-status" data-id="${v.id}">Change status · ${esc(v.status)} ↗</button></div>`:''}</section>
 <section class="detail-panel"><div class="detail-panel-head"><h3>Booking progress</h3><span>${v.bookings.length} total bookings</span></div><div class="progress-list">${bookingTypes.map(t=>{const counts=categoryCounts(v,t),pct=progress(v,t);return `<div class="progress-row"><div class="progress-head"><strong>${iconFor(t)} &nbsp;${t==='Transportation'?'Ground transport':t==='Restaurant'?'Restaurants':t==='Activity'?'Activities':t+'s'}</strong><span>${pct===null?'N/A':pct+'%'}</span></div>${pct===null?`<div class="progress-bar"><i style="width:0"></i></div>`:`<div class="progress-bar"><i style="width:${pct}%"></i></div>`}<div class="progress-foot">${counts.map(([s,n])=>n?`<span class="${s==='Done'?'done':s==='To Do'?'todo':''}">${s} ${n}</span>`:'').filter(Boolean).join('')||'<span>No active bookings</span>'}${counts.find(([s])=>s==='Cancelled')[1]?`<span>Cancelled ${counts.find(([s])=>s==='Cancelled')[1]}</span>`:''}</div></div>`;}).join('')}</div></section></div>
 <div class="section-title-row"><div><h3>Latest bookings</h3><p>A snapshot of the trip logistics</p></div><button class="small-link" data-tab="Guests">View guests →</button></div>${renderBookingGrid(v,v.bookings.slice(0,4))}`;
}
function renderGuests(v){const editable=canManageGuestData(v);return `<div class="section-title-row"><div><h3>Visit guests <span class="tab-count">${v.guests.length}</span></h3><p>Keep customer details and attendance up to date.</p></div>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div>${!v.guests.length?`<div class="empty-state panel"><div class="empty-symbol">♧</div><h3>No guests yet</h3><p>Add the people attending this customer visit.</p>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div>`:`<div class="table-list"><div class="data-row data-row-head"><div>Guest</div><div>Company</div><div>Attendance</div><div>Email</div><div></div></div>${v.guests.map(g=>`<div class="data-row"><div class="guest-primary">${guestAvatar(g)}<span><strong>${esc(g.firstName)} ${esc(g.lastName)}</strong><small class="guest-contact">${g.status==='Cancelled'?'Cancelled guest':g.profileId?'Axis team assignment':'Guest profile'}</small></span></div><div>${esc(g.company||'—')}</div><div>${`<select class="filter-select guest-status-select" data-guest-status="${g.id}" ${!editable||(g.profileId&&!canEdit(v))?'disabled':''}>${['Invited','Confirmed','Cancelled'].map(s=>`<option ${g.status===s?'selected':''}>${s}</option>`).join('')}</select>`}</div><div>${esc(g.email||'—')}</div><div>${editable?`<span class="guest-actions">${g.profileId&&!canEdit(v)?'':'<button class="inline-action" data-action="edit-guest" data-id="'+g.id+'" aria-label="Edit guest" title="Edit guest">Edit</button>'}${!canEdit(v)||g.profileId?'':'<button class="inline-action guest-remove" data-action="remove-guest" data-id="'+g.id+'" aria-label="Remove guest" title="Remove guest">Remove</button>'}</span>`:''}</div></div>${g.notes?`<div class="guest-note"><strong>Notes</strong><span>${esc(g.notes)}</span></div>`:''}`).join('')}</div>`}`;}
function renderGuests(v){
 const editable=canManageGuestData(v),canPublish=state.role==='SUPER_ADMIN'&&!v.archived&&!backendActive;
 const guideAction=v.travelGuidePublishedAt?'Manage guest guides':'Publish travel guides';
 const guideButton=canPublish&&v.guests.some(g=>!g.profileId&&g.status!=='Cancelled')?`<button class="secondary-button" data-action="publish-guide" data-id="${v.id}">${guideAction}</button>`:'';
 const teamNote=`<div class="notice-banner guest-flow-note"><strong>Guest access:</strong> clients receive a separate questionnaire and, when Monse publishes the itinerary, a private travel guide link and QR code. Guests never sign in to this dashboard. ${backendActive?'Live guest links and email delivery still need server setup.':'Local demo sends are simulated in this browser.'}</div>`;
 if(!v.guests.length)return `${teamNote}<div class="section-title-row"><div><h3>Visit guests <span class="tab-count">0</span></h3><p>Add clients with their name and email to prepare a questionnaire link.</p></div>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div><div class="empty-state panel"><div class="empty-symbol">♧</div><h3>No guests yet</h3><p>Add the people attending this customer visit.</p>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div>`;
 return `${teamNote}<div class="section-title-row"><div><h3>Visit guests <span class="tab-count">${v.guests.length}</span></h3><p>Client questionnaire, travel details and attendance.</p></div><div class="section-actions">${guideButton}${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add client</button>`:''}</div></div><div class="table-list"><div class="data-row data-row-head"><div>Guest</div><div>Company</div><div>Attendance</div><div>Contact / form</div><div>Actions</div></div>${v.guests.map(g=>{
   const formLabel=g.formStatus==='complete'?'Questionnaire received':g.formStatus==='sent'?'Questionnaire sent':'Questionnaire not sent';
   const canEditGuest=editable&&(!g.profileId||canEdit(v));
   const formAction=g.profileId||backendActive?'':`<button class="inline-action" data-action="guest-form-link" data-id="${g.id}" data-visit-id="${v.id}">${g.formStatus==='sent'?'Open form':'Send form'}</button>`;
   const flightAction=!g.profileId&&g.profile?.travelMode!=='Car'&&canEditFlightData(v)?`<button class="inline-action" data-action="guest-add-flight" data-id="${g.id}" data-visit-id="${v.id}">${v.bookings.some(b=>b.type==='Flight'&&b.guestIds.includes(g.id))?'Edit flight':'Add flight'}</button>`:'';
   const guideLink=!backendActive&&v.travelGuidePublishedAt&&!g.profileId&&g.status!=='Cancelled'?`<button class="inline-action" data-action="guest-guide-link" data-id="${g.id}" data-visit-id="${v.id}">Travel guide / QR</button>`:'';
   const profileAction=!g.profileId&&g.formStatus==='complete'?`<button class="inline-action" data-action="guest-profile" data-id="${g.id}" data-visit-id="${v.id}">View profile</button>`:'';
   const editAction=canEditGuest?`<button class="inline-action" data-action="edit-guest" data-id="${g.id}">Edit</button>`:'';
   const removeAction=canEdit(v)&&!g.profileId?`<button class="inline-action guest-remove" data-action="remove-guest" data-id="${g.id}">Remove</button>`:'';
   return `<div class="data-row"><div class="guest-primary">${guestAvatar(g)}<span><strong>${esc(g.firstName)} ${esc(g.lastName)}</strong><small class="guest-contact">${g.profileId?'Axis team member':esc(g.profile?.travelMode||'Travel method TBD')}</small></span></div><div>${esc(g.company||'—')}</div><div><select class="filter-select guest-status-select" data-guest-status="${g.id}" ${!editable||(g.profileId&&!canEdit(v))?'disabled':''}>${['Invited','Confirmed','Cancelled'].map(s=>`<option ${s===g.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="guest-contact-cell"><span>${esc(g.email||'—')}</span>${!g.profileId?`<small class="questionnaire-status status-${g.formStatus||'not-sent'}">${formLabel}</small>`:''}</div><div><span class="guest-actions">${formAction}${flightAction}${guideLink}${profileAction}${editAction}${removeAction}</span></div></div>${g.notes?`<div class="guest-note"><strong>Notes</strong><span>${esc(g.notes)}</span></div>`:''}`;
  }).join('')}</div>`;
}

function showGuestProfile(v,g){const p=g.profile||{};const rows=[['Phone',p.phone],['Company',p.company||g.company],['Title',p.title],['Allergies',p.allergies],['Favorite drink',p.favoriteDrink],['Birthday',p.birthday],['Social media consent',p.socialMediaConsent?'Yes':'No'],['Preferred name',p.preferredName],['Based in',p.whereBased],['Preferred language',p.preferredLanguage],['Travel method',p.travelMode],['Special request',p.specialRequest]];openModal('Client profile',`<p class="form-help">Information submitted through the guest questionnaire for <strong>${esc(g.firstName)} ${esc(g.lastName)}</strong>.</p><div class="guest-profile-review-grid">${rows.map(([label,value])=>`<div><small>${esc(label)}</small><strong>${esc(value||'—')}</strong></div>`).join('')}</div>`,`<button class="primary-button" data-action="close-modal">Done</button>`,null,true);}
function qrMarkup(link,id){return `<div class="guest-qr-wrap"><div class="guest-qr" id="guestQr${id}"></div><small>Scan to open this guest's travel guide</small></div>`;}
function fillGuestQr(link,id){try{if(!window.qrcode)throw new Error('QR generator is not available.');const qr=window.qrcode(0,'M');qr.addData(link);qr.make();const node=document.getElementById(`guestQr${id}`);if(node)node.innerHTML=qr.createSvgTag({cellSize:4,margin:3,scalable:true});}catch(error){console.error(error);}}
function showGuestFormLink(v,g){g.formToken=g.formToken||uid();if(g.formStatus!=='complete'){g.formStatus='sent';g.formSentAt=new Date().toISOString();}persist();const link=guestPortalUrl('form',g.formToken);openModal('Client questionnaire link',`<p class="confirmation-copy">A demo invitation is prepared for <b>${esc(g.firstName)} ${esc(g.lastName)}</b> at <b>${esc(g.email)}</b>. In this local demo, no email is sent; copy the link or preview the guest-only form.</p><div class="guest-link-copy"><input aria-label="Questionnaire link" readonly value="${esc(link)}"><button class="secondary-button" data-action="copy-link" data-url="${esc(link)}">Copy link</button></div><div class="guest-link-state">${g.formStatus==='complete'?'Questionnaire completed':'Demo email simulated · '+esc(g.formStatus||'ready')}</div>`,`<a class="primary-button" href="${esc(link)}" target="_blank" rel="noopener">Preview form</a><button class="secondary-button" data-action="close-modal">Close</button>`,null,true,'GUEST EXPERIENCE');}
function showGuestGuideLink(v,g){if(!v.travelGuidePublishedAt)return toast('Monse has not published this travel guide yet.',true);g.guideToken=g.guideToken||uid();const link=guestPortalUrl('guide',g.guideToken);openModal('Private guest travel guide',`<p class="confirmation-copy">This personal link opens the travel guide for <b>${esc(g.firstName)} ${esc(g.lastName)}</b>. Anyone with the link can view it, so share it only with this guest.</p><div class="guest-link-copy"><input aria-label="Travel guide link" readonly value="${esc(link)}"><button class="secondary-button" data-action="copy-link" data-url="${esc(link)}">Copy link</button></div>${qrMarkup(link,g.id)}<div class="guest-print-actions"><button class="secondary-button" data-action="print-guest-qr">Print QR code</button><a class="primary-button" href="${esc(link)}" target="_blank" rel="noopener">Preview travel guide</a></div>`,`<button class="secondary-button" data-action="close-modal">Close</button>`,null,true,'GUEST EXPERIENCE');fillGuestQr(link,g.id);}
function publishGuestGuides(v){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can publish travel guides.',true);if(v.travelGuidePublishedAt){showGuestGuideList(v);return;}const clients=v.guests.filter(g=>!g.profileId&&g.status!=='Cancelled');if(!clients.length)return toast('Add at least one client before publishing the guide.',true);openModal('Publish guest travel guides',`<p class="confirmation-copy">This will make an individual travel guide available to each active client and prepare their link and QR code. Guests will not receive dashboard access.</p><div class="notice-banner">Demo mode: links are created locally. No client emails are sent. Check the itinerary before sharing it.</div><p><strong>${clients.length}</strong> client${clients.length===1?'':'s'} will get a private guide link.</p>`,`<button class="secondary-button" data-action="close-modal">Keep planning</button><button class="primary-button" data-action="confirm-publish-guide" data-id="${v.id}">Publish guides</button>`,null,false,'GUEST EXPERIENCE');}
function showGuestGuideList(v){const clients=v.guests.filter(g=>!g.profileId&&g.status!=='Cancelled');const cards=clients.map(g=>{g.guideToken=g.guideToken||uid();const link=guestPortalUrl('guide',g.guideToken);return `<article class="guide-share-card"><div><strong>${esc(g.firstName)} ${esc(g.lastName)}</strong><small>${esc(g.email||'No email on file')}</small></div>${qrMarkup(link,g.id)}<div class="guest-link-copy"><input aria-label="Travel guide link" readonly value="${esc(link)}"><button class="secondary-button" data-action="copy-link" data-url="${esc(link)}">Copy</button></div><a class="primary-button" href="${esc(link)}" target="_blank" rel="noopener">Preview guide</a></article>`;}).join('');openModal('Guest travel guide links',`<p class="form-help">Published ${esc(new Date(v.travelGuidePublishedAt).toLocaleDateString())}. Each QR code opens a private, guest-specific guide. Share it with that guest only.</p><div class="guest-guide-share-list">${cards}</div>`,`<button class="secondary-button" data-action="print-guest-qr">Print QR codes</button><button class="primary-button" data-action="close-modal">Done</button>`,null,true,'GUEST EXPERIENCE');clients.forEach(g=>fillGuestQr(guestPortalUrl('guide',g.guideToken),g.id));persist();}
function copyGuestLink(link){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(link).then(()=>toast('Guest link copied.')).catch(()=>toast('Copy was blocked by the browser. Select and copy the link.',true));return;}const input=document.querySelector('.guest-link-copy input');if(input){input.select();document.execCommand('copy');toast('Guest link copied.');}}

function renderBookings(v,type){const list=v.bookings.filter(b=>b.type===type),editable=type==='Flight'?canEditFlightData(v):canEdit(v);return `<div class="section-title-row"><div><h3>${type==='Transportation'?'Ground transportation':type==='Restaurant'?'Restaurant reservations':type==='Activity'?'Planned activities':`${type}s`} <span class="tab-count">${list.length}</span></h3><p>${type==='Flight'?'Reps can enter flight segments for each guest':type==='Hotel'?'Shared hotel bookings and individual stays':type==='Transportation'?'Airport transfers and ground transport':type==='Restaurant'?'Dining plans and reservations':'Experiences planned for your guests'}</p></div>${editable?`<button class="primary-button" data-action="new-booking" data-type="${type}"><span class="plus">+</span> Add ${type==='Transportation'?'transport':type.toLowerCase()}</button>`:''}</div>${type==='Flight'&&list.length?`<div class="notice-banner">Flight information is entered by the assigned reps. Add each segment and assign the guests sharing that itinerary.</div>`:''}${!list.length?`<div class="empty-state panel"><div class="empty-symbol">${iconFor(type)}</div><h3>No ${type.toLowerCase()} bookings yet</h3><p>Add plans as details become available. You can update booking progress at any time.</p>${editable?`<button class="primary-button" data-action="new-booking" data-type="${type}"><span class="plus">+</span> Add ${type==='Transportation'?'transport':type.toLowerCase()}</button>`:''}</div>`:renderBookingGrid(v,list,type)}`;}
function renderBookingGrid(v,list){return `<div class="booking-grid">${list.map(b=>{const guests=b.guestIds.map(id=>v.guests.find(g=>g.id===id)).filter(Boolean);const location=b.location||(b.details?.from&&b.details?.to?`${b.details.from} → ${b.details.to}`:'');return `<article class="booking-card"><div class="booking-card-top"><div class="booking-glyph ${b.type.toLowerCase()}">${iconFor(b.type)}</div><div class="booking-name"><strong>${esc(b.name)}</strong><small>${esc(location||'Details to be confirmed')}${b.date?` · ${esc(fmtDate(b.date))}`:''}${b.time?` · ${esc(b.time)}`:''}</small></div>${statusPill(b.status)}</div>${b.type==='Flight'&&b.details?.segments?.length?`<div class="booking-route">${b.details.segments.map(s=>`<div class="route-segment"><span>${esc(s.from||'—')}</span><i></i><span>${esc(s.to||'—')}</span><small>${esc(s.flight||'Flight TBD')} · ${esc(s.date?fmtDate(s.date):'Date TBD')}</small></div>`).join('')}</div>`:''}${b.type==='Hotel'&&guests.length?`<div class="stay-summary">${guests.map(g=>{const stay=b.details.stays?.[g.id]||{checkIn:b.details.checkIn||b.date,checkOut:b.details.checkOut||b.endDate};return `<div><span>${esc(g.firstName)} ${esc(g.lastName)}</span><small>${stay.checkIn?fmtDate(stay.checkIn):'Check-in TBD'} – ${stay.checkOut?fmtDate(stay.checkOut):'Check-out TBD'}</small></div>`;}).join('')}</div>`:''}<div class="booking-card-foot"><span class="guest-avatars">${guests.slice(0,4).map(guestAvatar).join('')}${guests.length>4?`<span class="mini-avatar">+${guests.length-4}</span>`:''}${!guests.length?'<span>No guests assigned</span>':''}</span><span>${guests.length} ${guests.length===1?'guest':'guests'} ${b.details?.reference?`· Ref ${esc(b.details.reference)}`:''}</span><div class="booking-actions">${b.type==='Hotel'?'<button class="booking-export" data-action="export-hotel" data-visit-id="'+v.id+'" data-booking-id="'+b.id+'" aria-label="Download hotel request as Excel">Download Excel</button>':''}<button class="booking-edit" data-action="edit-booking" data-id="${b.id}" aria-label="Edit booking">Edit</button>${state.role==='SUPER_ADMIN'?`<button class="booking-delete" type="button" data-action="delete-booking" data-visit-id="${v.id}" data-booking-id="${b.id}" aria-label="Delete ${esc(b.type.toLowerCase())} booking">Delete</button>`:''}</div></div>${b.attachments?.length?`<div class="attachment-list">${b.attachments.map(a=>`<div class="attachment-item"><span>▧</span><a href="${esc(a.data)}" download="${esc(a.name)}">${esc(a.name)}</a>${canEdit(v)?`<button data-action="remove-attachment" data-id="${b.id}" data-attachment="${a.id}" aria-label="Remove attachment">×</button>`:''}</div>`).join('')}</div>`:''}${b.needsReview?`<div class="booking-needs-review"><span>◉ &nbsp;Needs review · ${esc(b.reviewReason||'Check details')}</span>${state.role==='SUPER_ADMIN'?`<button data-action="clear-review" data-id="${b.id}">Mark reviewed</button>`:''}</div>`:''}</article>`;}).join('')}</div>`;}
function loadXlsxLibrary(){if(window.XLSX)return Promise.resolve(window.XLSX);if(window.axisXlsxPromise)return window.axisXlsxPromise;window.axisXlsxPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='./xlsx.full.min.js?v=0.20.3';script.async=true;script.onload=()=>window.XLSX?resolve(window.XLSX):reject(new Error('Excel export library did not start.'));script.onerror=()=>{window.axisXlsxPromise=null;reject(new Error('Could not load the Excel export library.'));};document.head.append(script);});return window.axisXlsxPromise;}
async function downloadHotelRequest(v,b){try{const XLSX=await loadXlsxLibrary();const guests=(b.guestIds||[]).map(id=>v.guests.find(g=>g.id===id)).filter(Boolean);const rows=[['Visit','City','Country','Hotel','Hotel location','Booking date','Booking time','Guest first name','Guest last name','Guest email','Company','Check-in date','Check-out date','Late checkout','Confirmation number','Notes']];(guests.length?guests:[null]).forEach(g=>{const stay=g&&b.details.stays?.[g.id]||{};rows.push([v.name||'',v.city||'',v.country||'',b.name||'',b.location||'',b.date||'',b.time||'',g?.firstName||'',g?.lastName||'',g?.email||'',g?.company||'',stay.checkIn||b.details.checkIn||b.date||'',stay.checkOut||b.details.checkOut||b.endDate||'',b.details.lateCheckout?'Yes':'No',b.details.confirmationNumber||b.details.reference||'',b.details.notes||'']);});const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=[{wch:26},{wch:18},{wch:20},{wch:28},{wch:28},{wch:16},{wch:14},{wch:20},{wch:20},{wch:30},{wch:25},{wch:16},{wch:16},{wch:16},{wch:22},{wch:40}];if(rows.length>1)ws['!autofilter']={ref:'A1:P'+rows.length};const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Hotel request');const slug=[v.name,b.name].filter(Boolean).join('-').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase();XLSX.writeFile(wb,'hotel-reservation-'+(slug||'request')+'.xlsx',{compression:true});toast('Hotel request Excel file downloaded.');}catch(error){toast(error.message||'Could not create the Excel file.',true);}}
function renderActivity(v){return `<div class="section-title-row"><div><h3>Activity log</h3><p>A record of the changes made to this visit.</p></div></div>${v.activity.length?`<div class="log-list">${v.activity.map(a=>`<div class="log-entry"><span class="log-dot">${esc((a.actor||'A')[0])}</span><div class="log-copy"><strong>${esc(a.action)}</strong><p>${esc(a.detail)}</p><time>${esc(a.actor)} · ${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(a.at))}</time></div></div>`).join('')}</div>`:`<div class="empty-state panel"><div class="empty-symbol">◷</div><h3>No activity yet</h3><p>Important changes will appear here.</p></div>`}`;}

function openVisit(id,tab){const visit=state.visits.find(v=>v.id===id);if(!visit||!canView(visit)){toast('You do not have access to this visit.',true);return;}page.name='detail';page.visitId=id;if(tab)page.tab=tab;else page.tab='Overview';render();}
function render(){if(!backendActive)document.getElementById('roleSelect').value=state.demoUserId||'monse';if(page.name==='detail')renderDetail();else renderDashboard();updateNav();}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;document.getElementById('toastRegion').append(el);setTimeout(()=>el.remove(),3000);}
function openModal(title,body,footer,submit,wide=false,eyebrow='AXIS VISITS'){document.getElementById('modalTitle').textContent=title;document.getElementById('modalEyebrow').textContent=eyebrow;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalFooter').innerHTML=footer;document.querySelector('.modal').classList.toggle('wide',wide);document.getElementById('modalBackdrop').hidden=false;modalSubmit=submit;const first=document.querySelector('#modalBody input:not([type=hidden]),#modalBody select');if(first)setTimeout(()=>first.focus(),40);}
function closeModal(){document.getElementById('modalBackdrop').hidden=true;modalSubmit=null;}
function field(name,label,value='',type='text',optional=true,attrs=''){return `<div class="form-field"><label for="${name}">${label} ${optional?'<span class="optional">Optional</span>':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value||'')}" ${attrs}></div>`;}
function selectField(name,label,options,value='',optional=true){return `<div class="form-field"><label for="${name}">${label} ${optional?'<span class="optional">Optional</span>':''}</label><select id="${name}" name="${name}">${options.map(o=>`<option value="${esc(typeof o==='string'?o:o.value)}" ${value===(typeof o==='string'?o:o.value)?'selected':''}>${esc(typeof o==='string'?o:o.label)}</option>`).join('')}</select></div>`;}
function syncEventTeamGuests(v){const memberIds=[...new Set([v.lead,...(v.collaborators||[]),...(v.sales||[])].filter(Boolean))],selected=new Set(memberIds),removed=new Set();let changed=false;for(const personId of memberIds){const person=people.find(p=>p.id===personId);if(!person)continue;let guest=v.guests.find(g=>g.profileId===personId);if(!guest&&person.email)guest=v.guests.find(g=>!g.profileId&&g.email&&g.email.toLowerCase()===person.email.toLowerCase());if(guest){if(guest.profileId!==personId){guest.profileId=personId;changed=true;}continue;}const [firstName,...lastParts]=(person.name||'').split(' ');v.guests.push({id:uid(),profileId:personId,firstName:firstName||person.name,lastName:lastParts.join(' '),email:person.email||'',company:'Axis Lighting',status:'Confirmed',notes:''});changed=true;}v.guests=v.guests.filter(g=>{if(g.profileId&&!selected.has(g.profileId)){removed.add(g.id);changed=true;return false;}return true;});if(removed.size){for(const booking of v.bookings||[]){booking.guestIds=(booking.guestIds||[]).filter(id=>!removed.has(id));if(booking.details?.stays)for(const guestId of removed)delete booking.details.stays[guestId];}}return changed;}
function showNewVisit(){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can create official visits.',true);const vps=people.filter(p=>p.role==='VP');openModal('Create a visit',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name <span style="color:#d94f37">*</span></label><input id="name" name="name" placeholder="e.g. Montreal Client Visit" required maxlength="90"></div>${selectField('lead','Lead VP',vps.map(p=>({value:p.id,label:p.name})),vps[0].id,false)}<p class="form-help" style="grid-column:1/-1;margin:0">You can fill in the destination and dates as plans take shape.</p></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Create visit</button>`,data=>{const v={id:uid(),name:data.name.trim(),city:'',country:'',startDate:'',endDate:'',status:'Planning',lead:data.lead,collaborators:[],sales:[],archived:false,theme:['terracotta','blue','sage','night'][state.visits.length%4],guests:[],bookings:[],activity:[]};syncEventTeamGuests(v);log(v,'Visit created',`Created this visit and assigned ${personName(v.lead)} as Lead VP.`);state.visits.unshift(v);persist();closeModal();openVisit(v.id);toast('Visit created · Planning');});}
function showEditVisit(v){const vps=people.filter(p=>p.role==='VP'),editable=canEdit(v);if(!editable){toast('You do not have permission to edit this visit.',true);return;}const collabs=people.filter(p=>p.role==='VP'&&p.id!==v.lead);const sales=people.filter(p=>p.role==='SALES');openModal('Edit visit details',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name <span style="color:#d94f37">*</span></label><input id="name" name="name" value="${esc(v.name)}" required></div><div class="form-divider">Destination & dates</div>${field('city','City',v.city)}${field('country','Country',v.country)}${field('startDate','Start date',v.startDate,'date')}${field('endDate','End date',v.endDate,'date')}<div class="form-divider">Visit team</div>${selectField('lead','Lead VP',vps.map(p=>({value:p.id,label:p.name})),v.lead,false)}<div class="form-field"><label>Collaborating VPs <span class="optional">Optional</span></label><div class="check-group">${collabs.map(p=>`<label class="check-option"><input name="collaborators" value="${p.id}" type="checkbox" ${v.collaborators.includes(p.id)?'checked':''}>${esc(p.name.split(' ')[0])}</label>`).join('')}</div></div><div class="form-field full"><label>Sales team <span class="optional">Optional</span></label><div class="check-group">${sales.map(p=>`<label class="check-option"><input name="sales" value="${p.id}" type="checkbox" ${v.sales.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save changes</button>`,data=>{if(data.startDate&&data.endDate&&data.endDate<data.startDate){toast('End date must be the same as or later than start date.',true);return false;}const oldName=v.name,oldDates=`${v.startDate}|${v.endDate}`;Object.assign(v,{name:data.name.trim(),city:data.city.trim(),country:data.country.trim(),startDate:data.startDate,endDate:data.endDate,lead:data.lead,collaborators:(data.collaborators||[]).filter(id=>id!==data.lead),sales:data.sales||[]});const teamChanged=syncEventTeamGuests(v);if(teamChanged)log(v,'Event team guests synchronized','Updated the guest list to match the selected event team.');if(oldName!==v.name)log(v,'Visit details updated',`Visit name changed to ${v.name}.`);if(oldDates!==`${v.startDate}|${v.endDate}`){log(v,'Visit dates updated',`Dates changed to ${fmtRange(v.startDate,v.endDate)}.`);for(const b of v.bookings){const first=b.date||b.details?.checkIn, last=b.endDate||b.details?.checkOut||first;if(first&&((v.startDate&&first<v.startDate)||(v.endDate&&last>v.endDate))){b.needsReview=true;b.reviewReason='Booking is outside the updated visit dates';}}}persist();closeModal();render();toast('Visit details saved');});}
function showVisitStatus(v){if(state.role!=='SUPER_ADMIN')return;const options=visitStatuses;openModal('Change visit status',`<form id="modalForm"><div class="form-grid"><p class="form-help" style="grid-column:1/-1;margin:0">Choose the current planning stage for <b>${esc(v.name)}</b>.</p><div class="form-field full"><label for="status">Visit status</label><select id="status" name="status">${options.map(s=>`<option ${v.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div id="statusError" class="form-error" hidden></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save status</button>`,data=>{const error=document.getElementById('statusError');if(data.status==='Upcoming'&&(!v.city||!v.country||!v.startDate||!v.endDate)){error.hidden=false;error.innerHTML=`To move this visit to Upcoming, complete: ${[!v.city?'destination city':'',!v.country?'destination country':'',!v.startDate?'start date':'',!v.endDate?'end date':''].filter(Boolean).join(', ')}. <button type="button" class="small-link" data-action="edit-visit" data-id="${v.id}">Add details</button>`;return false;}if(data.status!==v.status){const old=v.status;v.status=data.status;log(v,'Visit status changed',`${old} → ${data.status}.`);}persist();closeModal();render();toast('Visit status updated');});}
function showNewGuest(v){if(!canManageGuestData(v))return toast('This visit is read-only.',true);openModal('Add a guest',`<form id="modalForm"><div class="form-grid">${field('firstName','First name','','text',false,'required')}${field('lastName','Last name','','text',false,'required')}${field('email','Email','','email')}${field('company','Company')}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea id="notes" name="notes" placeholder="Dietary needs, context, or other details"></textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Add guest</button>`,data=>{const g={id:uid(),firstName:data.firstName.trim(),lastName:data.lastName.trim(),email:data.email.trim(),company:data.company.trim(),status:'Invited',notes:data.notes.trim()};v.guests.push(g);log(v,'Guest added',`Added ${g.firstName} ${g.lastName}.`);persist();closeModal();render();toast('Guest added');});}
function showEditGuest(v,g){if(!canEdit(v)&&(!canManageGuestData(v)||g.profileId))return toast('This visit is read-only.',true);openModal('Edit guest details',`<form id="modalForm"><div class="form-grid">${field('firstName','First name',g.firstName,'text',false,'required')}${field('lastName','Last name',g.lastName,'text',false,'required')}${field('email','Email',g.email,'email')}${field('company','Company',g.company)}${selectField('status','Attendance status',['Invited','Confirmed','Cancelled'],g.status,false)}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea id="notes" name="notes" placeholder="Dietary needs, context, or other details">${esc(g.notes||'')}</textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save guest</button>`,data=>{const previousName=`${g.firstName} ${g.lastName}`,oldStatus=g.status;Object.assign(g,{firstName:data.firstName.trim(),lastName:data.lastName.trim(),email:data.email.trim(),company:data.company.trim(),notes:data.notes.trim()});log(v,'Guest details updated',`Updated ${previousName} to ${g.firstName} ${g.lastName}.`);if(data.status!==oldStatus){closeModal();changeGuest(v,g,data.status);return;}persist();closeModal();render();toast('Guest details saved');});}
function renderVisitRequestWorkflow(){
 if(!page || page.name!=='overview' || page.onlyReview || backendActive || !['SUPER_ADMIN','VP'].includes(state.role))return;
 const requests=(state.visitRequests||[]).filter(request=>state.role==='SUPER_ADMIN'?request.status==='pending':request.createdBy===currentUserId());
 const content=state.role==='SUPER_ADMIN'
  ? `<section class="panel request-panel"><div class="panel-head"><div><h2 class="panel-title">VP visit requests</h2><p class="panel-caption">Requests waiting for Monse to schedule</p></div><span class="request-count">${requests.length}</span></div>${requests.length?`<div class="request-list">${requests.map(request=>`<article class="visit-request-card"><div><strong>${esc(request.name)}</strong><p>${esc(personName(request.createdBy))} - ${esc(request.city)}, ${esc(request.country)} - ${esc(fmtRange(request.startDate,request.endDate))}</p><small>Reps: ${esc((request.sales||[]).map(personName).join(', ')||'None selected')}</small></div><button class="primary-button" data-action="create-from-request" data-id="${request.id}">Create visit</button></article>`).join('')}</div>`:'<div class="request-empty">No VP requests are waiting. When a VP submits one, it will appear here.</div>'}</section>`
  : `<section class="panel request-panel"><div class="panel-head"><div><h2 class="panel-title">Visit requests</h2><p class="panel-caption">Ask Monse to organize a customer visit</p></div><button class="primary-button" data-action="new-visit-request">Request a visit</button></div>${requests.length?`<div class="request-list">${requests.map(request=>`<article class="visit-request-card"><div><strong>${esc(request.name)}</strong><p>${esc(request.city)}, ${esc(request.country)} - ${esc(fmtRange(request.startDate,request.endDate))}</p><small>Request status: ${request.status==='pending'?'Waiting for Monse':'Visit created'}</small></div><span class="request-status ${request.status==='pending'?'pending':'scheduled'}">${request.status==='pending'?'Pending':'Scheduled'}</span></article>`).join('')}</div>`:'<div class="request-empty">You have no visit requests yet.</div>'}</section>`;
 const stats=document.querySelector('.stats-grid');
 const dashboard=document.querySelector('.dashboard-grid');
 if(stats)stats.insertAdjacentHTML('afterend',content);else if(dashboard)dashboard.insertAdjacentHTML('beforebegin',content);
}
const renderDashboardWithRequests=renderDashboard;
renderDashboard=function(){renderDashboardWithRequests();renderVisitRequestWorkflow();};
function showVisitRequestForm(){
 if(backendActive||state.role!=='VP')return toast('Visit requests are available in the local demo.',true);
 const reps=people.filter(person=>person.role==='SALES');
 openModal('Request a customer visit',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name</label><input id="name" name="name" placeholder="e.g. Boston Design Partner Visit" required maxlength="90"></div>${field('city','City','','text',false,'required')}${field('country','Country','','text',false,'required')}${field('startDate','Start date','','date',false,'required')}${field('endDate','End date','','date',false,'required')}<div class="form-field full"><label>Sales reps joining you</label><div class="check-group">${reps.map(person=>`<label class="check-option"><input name="sales" type="checkbox" value="${person.id}">${esc(person.name)}</label>`).join('')}</div></div><p class="form-help form-wide-note">This local demo request will be visible to Monse. Monse creates the official visit and then the selected team receives an in-app demo notification.</p></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Send request to Monse</button>`,data=>{
  if(data.endDate<data.startDate){toast('The end date must be on or after the start date.',true);return false;}
  state.visitRequests=state.visitRequests||[];
  state.visitRequests.unshift({id:uid(),name:data.name.trim(),city:data.city.trim(),country:data.country.trim(),startDate:data.startDate,endDate:data.endDate,createdBy:currentUserId(),sales:data.sales||[],status:'pending',createdAt:new Date().toISOString()});
  persist();closeModal();render();toast('Visit request sent to Monse in the local demo.');
 });
}
function createVisitFromRequest(request){
 if(backendActive||state.role!=='SUPER_ADMIN'||!request||request.status!=='pending')return;
 const reps=people.filter(person=>person.role==='SALES');
 openModal('Create visit from VP request',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name</label><input id="name" name="name" value="${esc(request.name)}" required maxlength="90"></div>${field('city','City',request.city,'text',false,'required')}${field('country','Country',request.country,'text',false,'required')}${field('startDate','Start date',request.startDate,'date',false,'required')}${field('endDate','End date',request.endDate,'date',false,'required')}<div class="form-field full"><label>Participating sales reps</label><div class="check-group">${reps.map(person=>`<label class="check-option"><input name="sales" type="checkbox" value="${person.id}" ${(request.sales||[]).includes(person.id)?'checked':''}>${esc(person.name)}</label>`).join('')}</div></div><p class="form-help form-wide-note">Lead VP: ${esc(personName(request.createdBy))}. The selected VP and reps will be added as event guests and receive demo notifications.</p></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Create visit and notify team</button>`,data=>{
  if(data.endDate<data.startDate){toast('The end date must be on or after the start date.',true);return false;}
  const visit={id:uid(),name:data.name.trim(),city:data.city.trim(),country:data.country.trim(),startDate:data.startDate,endDate:data.endDate,status:'Planning',lead:request.createdBy,collaborators:[],sales:data.sales||[],archived:false,theme:['terracotta','blue','sage','night'][state.visits.length%4],guests:[],bookings:[],activity:[]};
  syncEventTeamGuests(visit);log(visit,'Visit created',`Created this visit from ${personName(request.createdBy)}'s request.`);state.visits.unshift(visit);request.status='scheduled';request.linkedVisitId=visit.id;request.processedAt=new Date().toISOString();notifyVisitTeam(visit);persist();closeModal();openVisit(visit.id);toast('Visit created and team notified in the local demo.');
 });
}
